"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/changelog-pages/variants/01-sidebar";
const variants = {"sidebar":View0};
export interface ArtemisChangelogProps { className?: string; variant?: "sidebar"; }
export function ArtemisChangelog({ className, variant = "sidebar" }: ArtemisChangelogProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { useState } from "react";
import { ArtemisButtonLink } from "../../../foundations/button";
import { ArtemisSegmentedTabs } from "../../../foundations/segmented-tabs";
import { ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PANEL } from "../../../lib/ease";
type Category = "Product" | "Workflow" | "Connections";
type Filter = "all" | Category;
type Release = {
    id: string;
    title: string;
    date: string;
    category: Category;
    summary: string;
    points: readonly [
        string,
        string,
        string
    ];
};
const RELEASES: readonly Release[] = [
    {
        id: "canvas",
        title: "A canvas that keeps up with the room",
        date: "June 24, 2026",
        category: "Product",
        summary: "Working together on the same canvas now feels calmer. You can see where people are focused, follow a teammate, and keep every edit in step.",
        points: ["See where teammates are working", "Keep every edit in step", "Follow someone during a review"],
    },
    {
        id: "exports",
        title: "Repeat exports take one click",
        date: "June 10, 2026",
        category: "Workflow",
        summary: "Save the choices you use often and Workspace will remember the size, format, naming, and quality the next time around.",
        points: ["Save your usual export settings", "Prepare several files together", "Get smaller files with the same quality"],
    },
    {
        id: "connections",
        title: "Bring your work together",
        date: "May 28, 2026",
        category: "Connections",
        summary: "Connect Workspace with the tools your team already uses, keep project details in sync, and choose exactly what each connection can see.",
        points: ["Share new work automatically", "Keep project details in sync", "Choose what each connection can access"],
    },
    {
        id: "review",
        title: "A calmer way to review work",
        date: "May 14, 2026",
        category: "Product",
        summary: "Review links now open in a focused presentation surface with pinned comments, resolved threads, and per-frame approvals.",
        points: ["Approve individual moments", "Invite guests without extra setup", "Keep resolved feedback out of the way"],
    },
];
const FILTERS: readonly {
    value: Filter;
    label: string;
}[] = [
    { value: "all", label: "All" },
    { value: "Product", label: "Product" },
    { value: "Workflow", label: "Workflow" },
    { value: "Connections", label: "Connections" },
];
const LIST_SWAP: Transition = { duration: 0.16, ease: [0.4, 0, 1, 1] };
const NO_MOTION: Transition = { duration: 0 };
const countOf = (filter: Filter) => String(RELEASES.filter((r) => filter === "all" || r.category === filter).length).padStart(2, "0");
const TAB_ITEMS = FILTERS.map((f) => ({
    value: f.value,
    label: (<>
      <span>{f.label}</span>
      <span className="art:text-xs art:tabular-nums art:opacity-65">{countOf(f.value)}</span>
    </>),
}));
function CheckIcon() {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-check art:size-3" aria-hidden="true">
      <path d="M20 6 9 17l-5-5"/>
    </svg>);
}
export default function ChangelogPagesSidebar() {
    const reduce = useReducedMotion() ?? false;
    const [filter, setFilter] = useState<Filter>("all");
    const [switched, setSwitched] = useState(false);
    const releases = RELEASES.filter((r) => filter === "all" || r.category === filter);
    const rise = (y: number, delay: number, blur = false) => ({
        initial: reduce ? false : blur ? { opacity: 0, y, filter: "blur(4px)" } : { opacity: 0, y },
        animate: blur ? { opacity: 1, y: 0, filter: "blur(0px)" } : { opacity: 1, y: 0 },
        transition: reduce ? NO_MOTION : { ...ARTEMIS_SPRING_PANEL, delay },
    });
    const choose = (value: string) => {
        const next = FILTERS.find((f) => f.value === value)?.value;
        if (!next || next === filter)
            return;
        setSwitched(true);
        setFilter(next);
    };
    return (<>
      <main className="art:min-h-screen art:w-full art:bg-background art:px-4 art:py-12 art:font-sans art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-20">
        <div className="art:mx-auto art:w-full art:max-w-6xl">
          <section className="art:relative art:overflow-hidden art:rounded-3xl art:px-6 art:py-14 art:@min-[640px]/artemis:px-10 art:@min-[640px]/artemis:py-18 art:@min-[1024px]/artemis:px-12 art:@min-[1024px]/artemis:py-20">
            <div aria-hidden="true" className="art:pointer-events-none art:absolute art:-top-24 art:right-[-8%] art:h-72 art:w-4/5 art:rotate-[-7deg] art:bg-[linear-gradient(105deg,#f27777,#efc65b,#62c899,#58a9df,#f27777)] art:opacity-40 art:blur-3xl"/>
            <div className="art:relative">
              <motion.p className="art:font-medium art:text-muted-foreground art:text-sm" {...rise(8, 0.08)}>
                {"Notes from the team"}
              </motion.p>
              <motion.h1 className="art:mt-4 art:max-w-2xl art:text-balance art:leading-[1.04] art:tracking-[-0.05em] art:text-4xl art:@min-[768px]/artemis:text-5xl art:font-medium" {...rise(14, 0.17, true)}>
                {"Better work, explained simply."}
              </motion.h1>
              <motion.div {...rise(12, 0.29)}>
                <p className="art:mt-5 art:max-w-xl art:text-pretty art:text-muted-foreground art:leading-7">
                  {"The thoughtful changes making everyday projects feel clearer, quicker, and easier to share."}
                </p>
                <p className="art:mt-7 art:text-muted-foreground art:text-sm">
                  {"Updated June 24 \u00B7 New notes every few weeks"}
                </p>
              </motion.div>
            </div>
          </section>
          <div className="art:mt-10 art:grid art:min-w-0 art:grid-cols-1 art:gap-8 art:@min-[1024px]/artemis:grid-cols-[15rem_minmax(0,1fr)] art:@min-[1024px]/artemis:gap-12">
            <aside className="art:min-w-0 art:@min-[1024px]/artemis:sticky art:@min-[1024px]/artemis:top-8 art:@min-[1024px]/artemis:self-start">
              <div className="art:mb-5 art:hidden art:@min-[1024px]/artemis:block">
                <p className="art:font-semibold art:tracking-[-0.025em]">
                  {"Release notes"}
                </p>
                <p className="art:mt-1 art:text-muted-foreground art:text-sm">
                  {"Browse by area"}
                </p>
              </div>
              <div className="art:overflow-x-auto art:@min-[1024px]/artemis:overflow-visible">
                <ArtemisSegmentedTabs items={TAB_ITEMS} value={filter} onValueChange={choose} ariaLabel="Filter release notes" listClassName="art:inline-flex art:items-center art:gap-1 art:rounded-full art:bg-muted art:p-1 art:min-w-max art:@min-[1024px]/artemis:w-full art:@min-[1024px]/artemis:min-w-0 art:@min-[1024px]/artemis:flex-col art:@min-[1024px]/artemis:items-stretch art:@min-[1024px]/artemis:bg-muted art:@min-[1024px]/artemis:p-0" buttonClassName="art:rounded-full art:min-h-10 art:gap-6 art:@min-[1024px]/artemis:w-full art:@min-[1024px]/artemis:justify-between art:@min-[1024px]/artemis:px-4"/>
              </div>
            </aside>
            <div className="art:min-w-0">
              <AnimatePresence mode="wait">
                <motion.section key={filter} className="art:space-y-3" aria-live="polite" initial={reduce ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={reduce ? { opacity: 0, transition: NO_MOTION } : { opacity: 0, y: -6, transition: LIST_SWAP }} transition={reduce ? NO_MOTION : switched ? LIST_SWAP : { ...ARTEMIS_SPRING_LAYOUT, delay: 0.43 }}>
                  {releases.map((release, index) => (<motion.article key={release.id} className="art:rounded-2xl art:border art:border-border/60 art:bg-background art:p-5 art:@min-[640px]/artemis:p-7" initial={switched && !reduce ? { opacity: 0, y: 14 } : false} animate={{ opacity: 1, y: 0 }} transition={reduce ? NO_MOTION : ARTEMIS_SPRING_LAYOUT}>
                      <div className="art:flex art:flex-wrap art:items-center art:gap-2 art:text-muted-foreground art:text-sm">
                        <span>
                          {release.date}
                        </span>
                        <span aria-hidden="true">
                          {"\u00B7"}
                        </span>
                        <span>
                          {release.category}
                        </span>
                        {filter === "all" && index === 0 ? (<span className="art:ml-auto art:inline-flex art:rounded-full art:bg-[linear-gradient(105deg,#f27777,#efc65b,#62c899,#58a9df,#f27777)] art:p-px">
                            <span className="art:rounded-full art:bg-background art:px-2.5 art:py-1 art:font-medium art:text-foreground art:text-xs">
                              {"Latest"}
                            </span>
                          </span>) : null}
                      </div>
                      <h2 className="art:mt-4 art:max-w-2xl art:text-balance art:tracking-[-0.035em] art:text-4xl art:font-medium">
                        {release.title}
                      </h2>
                      <p className="art:mt-3 art:max-w-2xl art:text-pretty art:text-muted-foreground art:leading-7">
                        {release.summary}
                      </p>
                      <ul className="art:mt-6 art:grid art:gap-2 art:@min-[640px]/artemis:grid-cols-3">
                        {release.points.map((point) => (<li key={point} className="art:flex art:items-start art:gap-2.5 art:text-sm art:leading-6">
                            <span className="art:mt-1 art:grid art:size-5 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted">
                              <CheckIcon />
                            </span>
                            {point}
                          </li>))}
                      </ul>
                    </motion.article>))}
                </motion.section>
              </AnimatePresence>
              <section className="art:mt-5 art:flex art:flex-col art:items-start art:justify-between art:gap-6 art:rounded-2xl art:border art:border-border/60 art:bg-background art:p-6 art:@min-[640px]/artemis:flex-row art:@min-[640px]/artemis:items-center art:@min-[640px]/artemis:p-8">
                <div>
                  <p className="art:text-muted-foreground art:text-sm">
                    {"A calm monthly recap"}
                  </p>
                  <h2 className="art:mt-2 art:max-w-lg art:text-balance art:tracking-[-0.035em] art:text-4xl art:font-medium">
                    {"Get the changes worth knowing about."}
                  </h2>
                </div>
                <ArtemisButtonLink href="#" size="lg">
                  {"Subscribe"}
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-right art:size-4" aria-hidden="true">
                    <path d="M5 12h14"/>
                    <path d="m12 5 7 7-7 7"/>
                  </svg>
                </ArtemisButtonLink>
              </section>
            </div>
          </div>
        </div>
      </main>
    </>);
}
